import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'
SECRET_ADMIN_TOKEN = os.environ.get('ADMIN_TOKEN', 'changeme')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT DEFAULT 'general'
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, password_hash, role, department) VALUES ('admin', 'admin@corp.internal', ?, 'admin', 'engineering')",
               (hashlib.sha256(b'supersecret').hexdigest(),))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid session."""
    dept = request.args.get('department', '')
    page = request.args.get('page', '1')

    # Basic input length check
    if len(dept) > 100:
        return jsonify({'error': 'Input too long'}), 400

    # Build query - using string formatting for dynamic column filtering
    query = f"SELECT id, username, email, department FROM users WHERE department = '{dept}' LIMIT 20 OFFSET {(int(page)-1)*20}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, department, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/export', methods=['POST'])
def admin_export():
    """Admin-only endpoint to export user data."""
    token = request.headers.get('X-Admin-Token', '')
    if not token or token != SECRET_ADMIN_TOKEN:
        return jsonify({'error': 'Unauthorized'}), 403

    fmt = request.json.get('format', 'json')
    db = get_db()
    users = db.execute('SELECT id, username, email, department, role FROM users').fetchall()
    return jsonify({'count': len(users), 'data': [dict(u) for u in users]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000, debug=False)
